def resolve_endpoint(data_root: Path, project_id: str, logical_chat_id: str) -> dict[str, Any]:
    require_id(project_id, "project_id")
    chat_id = require_logical_id(logical_chat_id, "logical_chat_id")
    path = data_root / project_id / "endpoints" / f"{chat_id}.json"
    reject_reparse_components(path, data_root)
    if not path.is_file():
        fail("ENDPOINT_UNBOUND", chat_id)
    value = load_json(path)
    required = {
        "logical_chat_id", "mission_id", "generation", "active_endpoint_id", "active_endpoint_hmac",
        "predecessor_endpoint_hmac", "handoff_sha256", "restore_receipt_sha256",
        "study_gate_receipt_sha256", "state", "updated_at",
    }
    if not isinstance(value, dict) or set(value) != required:
        fail("ENDPOINT_SCHEMA", chat_id)
    if (value["logical_chat_id"] != chat_id or not isinstance(value["active_endpoint_id"], str)
            or not value["active_endpoint_id"] or not isinstance(value["generation"], int)
            or value["generation"] < 1 or value["state"] not in {"ACTIVE_INITIAL", "ACTIVE_SUCCESSOR"}):
        fail("ENDPOINT_INVALID", chat_id)
    key = load_or_create_hmac_key(data_root, project_id)
    if endpoint_hmac(value["active_endpoint_id"], key) != value["active_endpoint_hmac"]:
        fail("ENDPOINT_HMAC_MISMATCH", chat_id)
    return value


